const body = $json.body || $json;

const isAuthenticated = !!(body.user_context && body.user_context.is_authenticated);
const authToken = body.auth_token || '';
const userMessage = body.message;
const sessionId = body.session_id || 'unknown';

const systemPrompt = `Tu es l'agent paiement de Darimmo, une plateforme marocaine d'annonces immobilieres.

Ton role : informer un utilisateur AUTHENTIFIE sur le statut de ses propres transactions (boost d'annonce, etc.).

Regles strictes :
- N'invente aucune information sur une transaction. Toute information doit provenir du resultat d'un outil.
- Ne donne jamais d'information sur une transaction qui n'appartient pas a l'utilisateur connecte.
- Si un statut est failed ou pending, explique en langage clair sans inventer de cause technique precise que l'outil n'a pas fournie ; propose de contacter le support si le probleme persiste.
- N'effectue AUCUNE action de paiement toi-meme (tu ne crees ni ne modifies de transaction) - redirige vers les fonctionnalites de paiement existantes du site pour toute nouvelle operation (ex: booster une annonce se fait depuis la page de l'annonce).
- Reponds TOUJOURS dans la meme langue que le message de l'utilisateur. Si l'utilisateur ecrit en darija (arabe marocain, en caracteres latins ou arabes), en arabe standard, en francais ou en anglais, reponds dans cette meme langue.`;

const tools = [
  {
    name: "get_payment_status",
    description: "Recupere le statut d'une transaction precise de l'utilisateur connecte, par son identifiant.",
    parameters: {
      type: "OBJECT",
      properties: {
        transaction_id: { type: "NUMBER" }
      },
      required: ["transaction_id"]
    }
  },
  {
    name: "list_my_transactions",
    description: "Liste toutes les transactions de l'utilisateur connecte (boosts d'annonces, paiements, etc.).",
    parameters: { type: "OBJECT", properties: {} }
  }
];

return {
  json: {
    is_authenticated: isAuthenticated,
    auth_token: authToken,
    original_user_message: userMessage,
    session_id: sessionId,
    gemini_request_body: {
      contents: [{ role: "user", parts: [{ text: `${systemPrompt}\n\nMessage de l'utilisateur : "${userMessage}"` }] }],
      tools: [{ functionDeclarations: tools }]
    }
  }
};

return {
  json: {
    reply: "Vous devez etre connecte pour consulter vos paiements. Merci de vous connecter puis de reessayer.",
    session_id: $json.session_id,
    recommended_annonce_ids: [],
    intent: "payment_status",
    metadata: { agent_used: "payment_agent", tool_calls_count: 0, llm_calls_count: 0 }
  }
};

const prevData = $('Build Prompt And Tools').item.json;
const candidate = $json.candidates[0];
const parts = candidate.content.parts;
const functionCallPart = parts.find(p => p.functionCall);

if (!functionCallPart) {
  const textPart = parts.find(p => p.text);
  return {
    json: {
      needs_tool_call: false,
      direct_reply: textPart ? textPart.text : "Je n'ai pas compris votre demande.",
      session_id: prevData.session_id
    }
  };
}

const toolName = functionCallPart.functionCall.name;
const args = functionCallPart.functionCall.args;
const authToken = prevData.auth_token;

let django_url = '';

if (toolName === 'get_payment_status') {
  django_url = 'http://127.0.0.1:8000/api/payments/transactions/' + args.transaction_id + '/';
} else if (toolName === 'list_my_transactions') {
  django_url = 'http://127.0.0.1:8000/api/payments/transactions/';
}

return {
  json: {
    needs_tool_call: true,
    tool_name: toolName,
    tool_args: args,
    django_method: 'GET',
    django_url,
    auth_token: authToken,
    original_user_message: prevData.original_user_message,
    session_id: prevData.session_id
  }
};

return {
  json: {
    reply: $json.direct_reply,
    session_id: $json.session_id,
    recommended_annonce_ids: [],
    intent: "payment_status",
    metadata: { agent_used: "payment_agent", tool_calls_count: 0, llm_calls_count: 1 }
  }
};

const prevData = $('Extraire functionCall et preparer requete Django').item.json;
const djangoResult = $json;

return {
  json: {
    tool_name: prevData.tool_name,
    tool_result: djangoResult,
    original_user_message: prevData.original_user_message,
    session_id: prevData.session_id
  }
};

const d = $json;

const prompt = `Tu es l'agent paiement de Darimmo.

Outil appele : ${d.tool_name}
Resultat retourne par l'API : ${JSON.stringify(d.tool_result)}

Message original de l'utilisateur : "${d.original_user_message}"

Regles strictes :
- Base ta reponse UNIQUEMENT sur le resultat fourni ci-dessus. N'invente rien.
- Si le resultat contient une erreur (ex: 403, 404), explique clairement que cette transaction n'est pas accessible ou n'existe pas, sans detailler la cause technique.
- Si le statut est failed ou pending, explique en langage clair et propose de contacter le support si besoin.
- N'effectue aucune action de paiement toi-meme.
- Reponds TOUJOURS dans la meme langue que le message de l'utilisateur. Si l'utilisateur ecrit en darija (arabe marocain, en caracteres latins ou arabes), en arabe standard, en francais ou en anglais, reponds dans cette meme langue.`;

return {
  json: {
    gemini_request_body: { contents: [{ role: "user", parts: [{ text: prompt }] }] },
    session_id: d.session_id
  }
};

const replyText = $json.candidates[0].content.parts[0].text;
const prevData = $('Construire prompt final').item.json;

return {
  json: {
    reply: replyText,
    session_id: prevData.session_id,
    recommended_annonce_ids: [],
    intent: "payment_status",
    metadata: { agent_used: "payment_agent", tool_calls_count: 1, llm_calls_count: 2 }
  }
};
